import Image from "next/image";
import type { CSSProperties } from "react";
import Mock from "./Mock";
import Poster from "./Poster";
import sizes from "@/utils/shot-sizes.json";
import { siteLabel, type Work } from "@/utils/work";

type View = "devices" | "desktop" | "mobile" | "phones" | "cards" | "card" | "mock" | "art";

const PHONE_RATIO = 390 / 844;
const DESKTOP_RATIO = 16 / 10;
const CARD_RATIO = 9 / 16;

/** Width ÷ height of a screenshot, from utils/shot-sizes.json (generated by
 *  scripts/shot-sizes.mjs). Frames take this ratio so images are never cropped. */
function ratio(src: string | undefined, fallback: number) {
  const s = src ? (sizes as Record<string, number[]>)[src] : undefined;
  return s && s[0] && s[1] ? s[0] / s[1] : fallback;
}

const ar = (value: number) => ({ "--ar": value.toFixed(4) }) as CSSProperties;

/* A project screenshot presented on the project's colour: desktop shots sit in a
   browser frame, phone shots in a phone frame (several fan out together), store
   graphics as rounded cards, private work gets a drawn mock-up, illustrations sit on
   their own. Every frame takes its image's proportions, so nothing is cropped at the
   sides; `bleed` lets a desktop frame run off the bottom edge, the way studio sites
   crop them. */
export default function Shot({
  work,
  view,
  src,
  bleed = false,
  sizes: imageSizes = "(max-width: 860px) 100vw, 50vw",
  priority = false,
  className = "",
}: {
  work: Work;
  /** Which kind of shot to show; defaults to the best one the project has. */
  view?: View;
  /** A specific image for this slot (e.g. the second desktop shot). */
  src?: string;
  bleed?: boolean;
  sizes?: string;
  priority?: boolean;
  className?: string;
}) {
  const shots = work.shots ?? {};
  const phone = shots.mobile ?? shots.phones?.[0];
  const kind: View | undefined =
    view ??
    (shots.cover === "devices" && shots.desktop?.length && phone
      ? "devices"
      : shots.desktop?.length
        ? "desktop"
        : shots.phones?.length
          ? "phones"
          : shots.cards?.length
            ? "cards"
            : shots.mock
              ? "mock"
              : shots.art
                ? "art"
                : shots.mobile
                  ? "mobile"
                  : undefined);
  const image =
    src ??
    (kind === "desktop" || kind === "devices"
      ? shots.desktop?.[0]
      : kind === "mobile"
        ? phone
        : kind === "phones"
          ? shots.phones?.[0]
          : kind === "cards" || kind === "card"
            ? shots.cards?.[0]
            : kind === "art"
              ? shots.art
              : undefined);

  const style = { "--tile": work.color, "--glow": work.tone[1] } as CSSProperties;

  if (kind === "mock" && shots.mock) {
    return (
      <span className={`shot shot--mock ${className}`} style={style} data-shot>
        <Mock name={shots.mock} />
      </span>
    );
  }

  if (!kind || !image) {
    return (
      <span className={`shot shot--poster ${className}`} style={style} data-shot>
        <Poster work={work} className="poster--bare" showTitle={false} sizes={imageSizes} />
      </span>
    );
  }

  const browser = (img: string, imgSizes: string) => (
    <span className="shot__browser" style={ar(ratio(img, DESKTOP_RATIO))}>
      <span className="shot__bar" aria-hidden="true">
        <i />
        <i />
        <i />
        <span className="shot__url">{siteLabel(work)}</span>
      </span>
      <span className="shot__screen">
        <Image src={img} alt={`${work.title} — screenshot`} fill sizes={imgSizes} priority={priority} />
      </span>
    </span>
  );

  const handset = (img: string, alt: string, imgSizes: string, eager = priority) => (
    <span key={img} className="shot__phone" style={ar(ratio(img, PHONE_RATIO))}>
      <span className="shot__screen">
        <Image src={img} alt={alt} fill sizes={imgSizes} priority={eager} />
      </span>
    </span>
  );

  const card = (img: string, alt: string, imgSizes: string, eager = priority) => (
    <span key={img} className="shot__card" style={ar(ratio(img, CARD_RATIO))}>
      <Image src={img} alt={alt} fill sizes={imgSizes} priority={eager} />
    </span>
  );

  return (
    <span className={`shot shot--${kind} ${bleed ? "shot--bleed" : ""} ${className}`} style={style} data-shot>
      {kind === "devices" && phone && (
        <span className="shot__devices">
          {browser(image, imageSizes)}
          {handset(phone, `${work.title} on mobile`, "(max-width: 860px) 40vw, 18vw")}
        </span>
      )}
      {kind === "desktop" && browser(image, imageSizes)}
      {kind === "mobile" && handset(image, `${work.title} on mobile`, "(max-width: 860px) 60vw, 22vw")}
      {kind === "phones" && (
        <span className="shot__fan" style={ar(ratio(shots.phones![0], PHONE_RATIO))}>
          {shots.phones!.slice(0, 3).map((p, i) =>
            handset(p, `${work.title} on mobile — screen ${i + 1}`, "(max-width: 860px) 40vw, 18vw", priority && i === 0),
          )}
        </span>
      )}
      {kind === "cards" && (
        <span className="shot__fan shot__fan--cards" style={ar(ratio(shots.cards![0], CARD_RATIO))}>
          {shots.cards!.slice(0, 3).map((c, i) =>
            card(c, `${work.title} — app store screen ${i + 1}`, "(max-width: 860px) 40vw, 18vw", priority && i === 0),
          )}
        </span>
      )}
      {kind === "card" && (
        <span className="shot__single">{card(image, `${work.title} — app store screen`, "(max-width: 860px) 60vw, 22vw")}</span>
      )}
      {kind === "art" && (
        <span className="shot__art">
          <Image src={image} alt={`${work.title} — illustration`} fill sizes={imageSizes} priority={priority} />
        </span>
      )}
    </span>
  );
}
